import{_ as l,o,c as a,a5 as r}from"./chunks/framework.Cooo9kuv.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"842-提取txt文档名称和内容前N个字符生成新的目录文档","日期":"2026-04-13T00:00:00.000Z","修改日期":"2026-04-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["TXT文件批处理"],"标签":["Python TXT批量处理脚本","TXT文件目录生成工具","TXT文档摘要提取","乱码TXT文件处理","办公TXT批量管理工具","多文件夹TXT批量汇总","子文件夹TXT提取工具","批量处理只读TXT文件","批量提取每个txt文档名称和文档内指定数量的内容并创建预览txt文档"]},"headers":[],"relativePath":"md/TXT文件批处理/842-提取txt文档名称和内容前N个字符生成新的目录文档.md","filePath":"md/TXT文件批处理/842-提取txt文档名称和内容前N个字符生成新的目录文档.md"}'),n={name:"md/TXT文件批处理/842-提取txt文档名称和内容前N个字符生成新的目录文档.md"};function e(i,t,p,s,T,_){return o(),a("div",null,[...t[0]||(t[0]=[r('<p>可批量处理文件夹（含可选子文件夹）中的 TXT 文件，提取每个txt文档的<strong>文件名</strong>和<strong>内容前 N 个字符</strong>，并按原文件夹名称生成汇总文档，方便快速预览多个 TXT 文件的核心信息。</p><p>批量提取每个txt文档名称和文档内指定数量的内容，创建一个预览txt文档。</p><p>自动检测txt文档编码，写入新的txt文档时以UTF-8</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20251119212843176355892363941.png" alt=""></p><h3 id="核心参数设置" tabindex="-1">核心参数设置 <a class="header-anchor" href="#核心参数设置" aria-label="Permalink to &quot;核心参数设置&quot;">​</a></h3><p>（1）输入文件夹路径</p><ul><li>点击「选择输入文件夹」，选中包含 TXT 文件的根目录</li><li>支持手动输入文件夹绝对路径（需确保路径有效）</li></ul><p>（2）子文件夹穿透</p><ul><li>勾选「勾选则穿透子文件夹」，工具会递归处理所有子文件夹中的 TXT 文件</li><li>不勾选则仅处理根目录下的 TXT 文件</li></ul><p>（3）输出路径设置</p><ul><li>默认：汇总文档保存到对应文件夹内（文件名与文件夹名一致）</li><li>勾选「保存到指定文件夹」，可自定义汇总文档的保存目录（需单独选择有效文件夹）</li></ul><p>（4）提取字符数</p><ul><li>默认提取每个 TXT 文件前 1500 个字符</li><li>可手动输入正整数（无效值会自动恢复为默认 1500）</li></ul><ol start="3"><li>开始处理</li></ol><ul><li>确认所有参数设置完成后，点击「开始处理」</li><li>处理过程中会自动取消 TXT 文件的只读属性（避免无法写入）</li><li>进度条实时显示处理进度，日志框输出详细操作记录</li></ul><ol start="4"><li>结果说明</li></ol><ul><li>每个文件夹（含子文件夹）会生成一个汇总文档（如<code>文件夹A.txt</code>）</li><li>汇总文档内容格式：<code>文件名═════════下滑试看═════════文件前N字符内容</code></li><li>处理完成后会弹出提示框，日志框可查看成功 / 失败详情</li></ul><h3 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h3><p><strong>Q1：点击「开始处理」无响应？</strong></p><p>A1：检查输入 / 输出文件夹路径是否有效，提取字符数是否为正整数，未满足条件会导致按钮禁用。</p><p><strong>Q2：处理后汇总文档乱码？</strong></p><p>A2：工具会自动适配编码，若仍乱码，可手动确认原 TXT 文件编码查看原文档是否本身就是乱码。</p><p><strong>Q3：无法取消文件只读属性？</strong></p><p>A3：确保文件夹有读写权限，或右键文件夹→「属性」→取消「只读」勾选，重新尝试处理。</p><h3 id="q4-子文件夹中的-txt-文件未被处理" tabindex="-1">Q4：子文件夹中的 TXT 文件未被处理？ <a class="header-anchor" href="#q4-子文件夹中的-txt-文件未被处理" aria-label="Permalink to &quot;Q4：子文件夹中的 TXT 文件未被处理？&quot;">​</a></h3><p>A4：需勾选「勾选则穿透子文件夹」，否则仅处理根目录文件。</p><h3 id="📑-程序使用环境及相关说明" tabindex="-1">📑 程序使用环境及相关说明 <a class="header-anchor" href="#📑-程序使用环境及相关说明" aria-label="Permalink to &quot;📑 程序使用环境及相关说明&quot;">​</a></h3><blockquote><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p></blockquote><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2171.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2171.html</a></p>',30)])])}const d=l(n,[["render",e]]);export{g as __pageData,d as default};
